      {
        role: 'assistant',
        content: 'hidden',
        timestamp: '2026-09-30T08:00:01.000Z',
        isStreaming: false,
        suppressed: true,
      }
    );
    const {base} = await startEngine(store, RESUME_ON);

    const frames = await connectAndSettle(`${base}?sessionId=known`);

    expect({
      types: frames.map(({type, index}) => (index === undefined ? type : `${type} ${index}`)),
      leaked: JSON.stringify(frames).includes('hidden'),
    }).toEqual({types: ['connected', 'entry_upsert 0', 'entry_skip 1', 'pong'], leaked: false});
  });

  it('replays an answer suppressed while it was still open as skips, as blank as the live client was left', async () => {
    const {base} = await startEngine(new InMemorySessionStore(), RESUME_ON, suppressingMidAnswer);
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    const replayed = JSON.stringify(frames);
    expect({
      types: frames.map(({type, index}) => (index === undefined ? type : `${type} ${index}`)),
      leaked: ['before', 'after'].filter(word => replayed.includes(word)),
    }).toEqual({types: ['connected', 'entry_upsert 0', 'entry_skip 1', 'entry_skip 2', 'pong'], leaked: []});
  });

  it('replays an entry whose turn is still running as finished and truncated, leaving the stored entry as it is', async () => {
    const store = new InMemorySessionStore();
    const known = await store.create('known', 'u1');
    known.entries.push({role: 'user', content: 'hello', timestamp: '2026-09-30T08:00:00.000Z'}, {...HALF_ANSWER});
    const {base} = await startEngine(store, RESUME_ON);

    const frames = await connectAndSettle(`${base}?sessionId=known`);

    expect({replayed: upserts(frames)[1], stored: known.entries[1]}).toEqual({
      replayed: {index: 1, entry: {...HALF_ANSWER, isStreaming: false, truncated: true}},
      stored: HALF_ANSWER,
    });
  });

  it('keeps a resumed session whose socket closed before the replay, rather than evicting it', async () => {
    const inner = new InMemorySessionStore();
    const known = await inner.create('known', 'u1');
    known.entries.push({role: 'user', content: 'earlier', timestamp: '2026-09-30T08:00:00.000Z'});
    const lookupHeld = deferredRelease();
    const evicted: string[] = [];
    const store: SessionStore = {
      create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
      get: async sessionId => {
        await lookupHeld.until;
        return inner.get(sessionId);
      },
      delete: sessionId => inner.delete(sessionId),
      count: () => inner.count(),
      clear: () => inner.clear(),
      evict: sessionId => {
        evicted.push(sessionId);
        return inner.evict(sessionId);
      },
    };
    const {base, firstServerClose} = await startEngine(store, RESUME_ON);

    const client = open(`${base}?sessionId=known`);
    await once(client, 'open');
    // Terminated, not closed: the server holds the socket paused across the lookup, so it never reads a close frame.
    client.terminate();
    await firstServerClose;
    lookupHeld.release();
    await new Promise(resolve => setTimeout(resolve, 50));

    const kept = inner.get('known');
    expect({evicted, kept: kept?.entries.length}).toEqual({evicted: [], kept: 1});
  });

  it('with resume off, still completes a handshake at /hal/ws/undefined and mints an id', async () => {
    const {base} = await startEngine(new InMemorySessionStore());

    const frames = await connectAndSettle(`${base}/undefined`);

    expect(frames[0]).toMatchObject({type: 'connected', sessionId: expect.stringMatching(/^[0-9a-f-]{36}$/)});
  });

  it('still types a connected frame literal that carries neither resume field', () => {
    const legacy: ConnectedMessage = {type: 'connected', sessionId: 's1', message: 'hi', examplePrompts: []};

    expect(Object.keys(legacy)).toEqual(['type', 'sessionId', 'message', 'examplePrompts']);
  });
});

describe('continuing the latest session', () => {
  it('with latest on, rejoins the most recently active session of a user whose connect names none', async () => {
    const store = storeWith([
      ['older', 'u1', '2026-09-30T08:00:00.000Z'],
      ['newer', 'u1', '2026-09-30T09:00:00.000Z'],
      ['theirs', 'u2', '2026-09-30T10:00:00.000Z'],
    ]);
    const {base, connects} = await startEngine(store, LATEST_ON);

    const frames = await connectAndSettle(base);

    expect({connected: frames[0], replay: upserts(frames), connects}).toMatchObject({
      connected: {sessionId: 'newer', resumed: true, entryCount: 1},
      replay: [{index: 0, entry: {role: 'user', content: 'newer'}}],
      connects: [{sessionId: 'newer', resumed: true}],
    });
  });

  it('with latest on, starts a new session for a user with none, and on ?new=1 even when one exists', async () => {
    const store = storeWith([['known', 'u1', '2026-09-30T08:00:00.000Z']]);
    const {auth, base} = await startEngine(store, LATEST_ON);

    const asked = await connectAndSettle(`${base}?new=1`);
    auth.userId = 'u2';
    const firstVisit = await connectAndSettle(base);

    expect({
      asked: {resumed: asked[0].resumed, minted: asked[0].sessionId !== 'known'},
      firstVisit: {resumed: firstVisit[0].resumed, minted: firstVisit[0].sessionId !== 'known'},
      held: store.count(),
    }).toEqual({asked: {resumed: false, minted: true}, firstVisit: {resumed: false, minted: true}, held: 3});
  });

  it('with latest on, still rejoins the session a connect names rather than the latest one', async () => {
    const store = storeWith([
      ['older', 'u1', '2026-09-30T08:00:00.000Z'],
      ['newer', 'u1', '2026-09-30T09:00:00.000Z'],
    ]);
    const {base} = await startEngine(store, LATEST_ON);

    const frames = await connectAndSettle(`${base}?sessionId=older`);

    expect(frames[0]).toMatchObject({sessionId: 'older', resumed: true});
  });

  it("starts a new session when the store's latestFor answers another user's session, throws, or is absent", async () => {
    const inner = storeWith([['theirs', 'u2', '2026-09-30T08:00:00.000Z']]);
    const stores: Record<string, SessionStore> = {
      stranger: {...delegatingTo(inner), latestFor: () => inner.get('theirs')},
      failing: {
        ...delegatingTo(inner),
        latestFor: () => {
          throw new Error('database down');
        },
      },
      absent: delegatingTo(inner),
    };

    const outcomes: Record<string, unknown> = {};
    for (const [name, store] of Object.entries(stores)) {
      const {base} = await startEngine(store, LATEST_ON);
      const [connected] = await connectAndSettle(base);
      outcomes[name] = {resumed: connected.resumed, minted: connected.sessionId !== 'theirs'};
    }

    const fresh = {resumed: false, minted: true};
    expect(outcomes).toEqual({stranger: fresh, failing: fresh, absent: fresh});
  });

  it('with resume on but latest off, starts a new session for a connect that names none', async () => {
    const store = storeWith([['known', 'u1', '2026-09-30T08:00:00.000Z']]);
    const {base} = await startEngine(store, RESUME_ON);

    const [connected] = await connectAndSettle(base);

    expect({resumed: connected.resumed, minted: connected.sessionId !== 'known'}).toEqual({
      resumed: false,
      minted: true,
    });
  });
});

// A store whose only session, the one u1 had, outlived its one-millisecond lifetime before anyone asked for it.
const agedOut = async (): Promise<InMemorySessionStore> => {
  const store = new InMemorySessionStore({maxAgeMs: 1});
  const {entries} = store.create('known', 'u1');
  entries.push({role: 'user', content: 'my booking 4711', timestamp: '2026-09-30T08:00:00.000Z'});
  await new Promise(resolve => setTimeout(resolve, 20));
  return store;
};

describe('telling an expired session apart', () => {
  it('tells the owner of a session that aged out that it expired, with a new id and no replay', async () => {
    const {base} = await startEngine(await agedOut(), RESUME_ON);

    const frames = await connectAndSettle(`${base}?sessionId=known`);

    expect({
      connected: frames[0],
      minted: frames[0].sessionId !== 'known',
      replayed: upserts(frames).length,
    }).toMatchObject({
      connected: {resumed: false, resumeFailure: 'expired'},
      minted: true,
      replayed: 0,
    });
  });

  it('answers another user naming an expired id exactly as it answers an id never issued', async () => {
    const {auth, base} = await startEngine(await agedOut(), RESUME_ON);
    auth.userId = 'u2';

    const expired = await connectAndSettle(`${base}?sessionId=known`);
    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);

    expect({expired: shapeOf(expired), failure: expired[0].resumeFailure}).toEqual({
      expired: shapeOf(neverIssued),
      failure: 'unknown',
    });
  });

  it('sends no resumeFailure at all when the connect names no id, even with no latest session to rejoin', async () => {
    const {base} = await startEngine(new InMemorySessionStore(), LATEST_ON);

    const [connected] = await connectAndSettle(base);

    expect({resumed: connected.resumed, failureKey: 'resumeFailure' in connected}).toEqual({
      resumed: false,
      failureKey: false,
    });
  });

  it('reads a named id with one call per attempt: lookup when the store has it, get otherwise', async () => {
    const inner = storeWith([['known', 'u1', '2026-09-30T08:00:00.000Z']]);
    const calls: string[] = [];
    const fiveMembers: SessionStore = {
      ...delegatingTo(inner),
      get: sessionId => {
        calls.push('get');
        return inner.get(sessionId);
      },
    };
    const withLookup: SessionStore = {
      ...fiveMembers,
      lookup: sessionId => {
        calls.push('lookup');
        return inner.lookup(sessionId);
      },
    };

    const outcomes: Record<string, unknown> = {};
    for (const [name, store] of Object.entries({fiveMembers, withLookup})) {
      const {base} = await startEngine(store, RESUME_ON);
      const [live] = await connectAndSettle(`${base}?sessionId=known`);
      const [dead] = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
      outcomes[name] = {live: live.resumed, dead: dead.resumeFailure};
    }

    const answered = {live: true, dead: 'unknown'};
    expect({outcomes, calls}).toEqual({
      outcomes: {fiveMembers: answered, withLookup: answered},
      calls: ['get', 'get', 'lookup', 'lookup'],
    });
  });
});
   100	
   101	All messages are JSON objects containing a REQUIRED `type` field that identifies the message kind. Additional fields depend on the message type.
   102	
   103	```json
   104	{
   105	  "type": "<message_type>",
   106	  ...
   107	}
   108	```
   109	
   110	A client receiving a message with an unrecognized `type` SHOULD ignore it, so that additive protocol changes do not break older clients. The server does NOT ignore unknown types: it replies with an `error` carrying code `INVALID_MESSAGE` (Section 5.6).
   111	
   112	## 4. Client-to-Server Messages
   113	
   114	### 4.1 user_message
   115	
   116	Sends a user chat message. `user_message` is the only accepted type: the server previously also took `send_message`, which was removed before the first published release.
   117	
   118	```json
   119	{
   120	  "type": "user_message",
   121	  "content": "What is the weather in Berlin?"
   122	}
   123	```
   124	
   125	| Field     | Type   | Required | Description      |
   126	| --------- | ------ | -------- | ---------------- |
   127	| `type`    | string | Yes      | `"user_message"` |
   128	| `content` | string | Yes      | Message text     |
   129	
   130	Any other field is ignored, and the validator forwards only the fields the frame defines. In particular the server does not read a `chatId` from this message: the connection already determines the session ([validated by: drops any field the frame does not define, rather than forwarding it](../../src/transport/ws/validation.test.ts#L18)).
   131	
   132	Constraints:
   133	
   134	- `content` MUST NOT be empty or whitespace-only after trimming.
   135	- `content` MUST NOT exceed 10,000 characters.
   136	- Violation of these constraints results in an `error` response with code `INVALID_MESSAGE`.
   137	
   138	One at a time:
   139	
   140	- A session processes one `user_message` at a time, in the order the frames arrived: a frame arriving while an earlier one is still running waits, and its answer starts only after the earlier run's `stream_end` ([validated by: answers a second user_message only after the first has sent its stream_end, in the order they arrived](../../src/transport/ws/messageHandler.test.ts#L680)).
   141	- The waiting message's model request therefore holds the earlier answer finished, never one still streaming ([validated by: hands the second run a history whose first answer is finished, never one still streaming](../../src/transport/ws/messageHandler.test.ts#L711)).
   142	- A `ping` is answered at once, even while a run is pending ([validated by: answers a ping at once while a run is pending](../../src/transport/ws/messageHandler.test.ts#L729)).
   143	- A frame that fails validation and is not a `user_message`, such as a malformed `ping`, gets its `INVALID_MESSAGE` at once, even while a run is pending, but a `user_message` that fails validation is answered in turn, its `INVALID_MESSAGE` and `stream_end` after the run in progress, since an `error` frame names no message and would otherwise read as the running answer's ([validated by: answers an invalid ping at once but an invalid user_message in turn, after the run in progress](../../src/transport/ws/messageHandler.test.ts#L742)).
   144	- The reconnect flush (§ 11.3), which sends queued messages in one burst, is therefore safe: they are answered one after another, in the order the user typed them ([validated by: queues three messages sent in one tick before the handler returns, and answers them in that order](../../src/transport/ws/messageHandler.test.ts#L758)).
   145	- A queued message whose socket has closed by the time its turn comes is dropped, neither recorded nor answered, since nobody is left to read the answer and a session whose last socket closed has no credentials left ([validated by: drops a queued message whose socket closed before its turn, without asking the model or recording it](../../src/transport/ws/messageHandler.test.ts#L775)).
   146	
   147	### 4.2 ping
   148	
   149	Application-level heartbeat. The server MUST respond with a `pong` message echoing the timestamp.
   150	
   151	```json
   152	{
   153	  "type": "ping",
   154	  "timestamp": 1705312200000
   155	}
   156	```
   157	
   158	| Field       | Type   | Required | Description                      |
   159	| ----------- | ------ | -------- | -------------------------------- |
   160	| `type`      | string | Yes      | `"ping"`                         |
   161	| `timestamp` | number | Yes      | Client timestamp in milliseconds |
   162	
   163	### 4.3 list_sessions
   164	
   165	Asks for the authenticated connection's conversation summaries. The request has no `userId` field: the server derives the user from the connection, and ignores an extra client-supplied `userId`. It forwards `limit` and `before` unchanged to the session store.
   166	
   167	```json
   168	{
   169	  "type": "list_sessions",
   170	  "limit": 10,
   171	  "before": {"sessionId": "previous-session", "updatedAt": "2026-10-01T00:00:00.000Z"}
   172	}
   173	```
   174	
   175	| Field    | Type    | Required | Description                                                                 |
   176	| -------- | ------- | -------- | --------------------------------------------------------------------------- |
   177	| `type`   | string  | Yes      | `"list_sessions"`                                                           |
   178	| `limit`  | integer | No       | Non-negative maximum number of summaries                                    |
   179	| `before` | object  | No       | Cursor with a 1–128-character `sessionId` and a valid `updatedAt` timestamp |
   180	
   181	An invalid `limit` or cursor is refused with `INVALID_MESSAGE` without calling the store ([validated by: accepts a list_sessions cursor and rejects malformed list pagination fields](../../src/transport/ws/validation.test.ts#L24)).
   182	
   183	## 5. Server-to-Client Messages
   184	
   185	### 5.1 connected
   186	
   187	Sent exactly once after a successful handshake. See Section 2.3.
   188	
   189	| Field            | Type     | Description                                                                                                                                                                                                                                                                                         |
   190	| ---------------- | -------- | --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |
   191	| `type`           | string   | `"connected"`                                                                                                                                                                                                                                                                                       |
   192	| `sessionId`      | string   | UUID v4 identifying the session                                                                                                                                                                                                                                                                     |
   193	| `message`        | string   | Human-readable greeting                                                                                                                                                                                                                                                                             |
   194	| `examplePrompts` | string[] | Example queries derived from registered tool definitions                                                                                                                                                                                                                                            |
   195	| `resumed`        | boolean  | Present only with resume enabled: whether the requested conversation was rejoined                                                                                                                                                                                                                   |
   196	| `entryCount`     | number   | Present only when `resumed` is `true`: how many stored entries the replay covers, skipped ones included                                                                                                                                                                                             |
   197	| `resumeFailure`  | string   | Present only when the connection named an id and `resumed` is `false`: `expired` when the caller's own session aged out, `unknown` otherwise. `unknown` deliberately covers both an id the server never issued and one that is not the caller's, so the answer reveals nothing about ids that exist |
   198	
   199	### 5.2 entry_upsert
   200	
   201	Creates a new entry or replaces an existing entry at the given index. This is the primary mechanism for adding content to the conversation.
   202	
   203	```json
   204	{
   205	  "type": "entry_upsert",
   206	  "index": 0,
   207	  "entry": {
   208	    "role": "user",
   209	    "content": "What is the weather in Berlin?",
   210	    "timestamp": "2026-01-15T14:30:00Z"
   211	  }
   212	}
   213	```
   214	
   215	| Field   | Type         | Description                            |
   216	| ------- | ------------ | -------------------------------------- |
   217	| `type`  | string       | `"entry_upsert"`                       |
   218	| `index` | number       | Zero-based position in the entry array |
   219	| `entry` | SessionEntry | The entry object (see Section 6)       |
   220	
     1	# Conversation List
     2	
     3	| Field  | Value                 |
     4	| ------ | --------------------- |
     5	| Issue  | re-cinq/HALEngine#143 |
     6	| Status | Shipped               |
     7	
     8	Resume gets a client back into one conversation: the id it names, or the user's most recently active one. Neither tells it which conversations exist, and every other member of `SessionStore` answers about a session the caller can already name, so a consumer wanting to offer a conversation list had to query the collection behind the engine's back, against a document shape and a key the engine owns. `listFor` answers the list instead, as summaries rather than sessions. **GDPR.** A summary is personal data — that a user held a conversation, and when — so it carries no conversation content, it is filtered to one user by the query rather than in application code afterwards, and the retention bound stays the consumer's, through the store's `maxAgeMs` and erasure methods and re-cinq/HALEngine#41.
     9	
    10	## The summary
    11	
    12	- A summary is `sessionId`, `createdAt`, `updatedAt` and `entryCount`, and nothing else: neither the conversation's entries nor its credentials, so a list can never hand over either, even for a session created with credentials ([validated by: carries only its four fields, so a list can never hand over a conversation or a credential](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L22)).
    13	- `listFor` is optional, like `latestFor` and `lookup` before it: a store written against the five original members still satisfies the interface, and both shipped stores implement it ([validated by: leaves a store with only the five original members satisfying the interface beside both shipped ones](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L11)).
    14	
    15	## The order a list answers in
    16	
    17	- Summaries come back most recent activity first ([validated by: answers newest activity first, headed by the very session latestFor returns](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L27)).
    18	- The first summary is the session `latestFor` returns, because both read the same activity ([validated by: answers newest activity first, headed by the very session latestFor returns](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L27)).
    19	- The order is total rather than merely sorted: two conversations last active in the same millisecond are ordered by session id, the larger first, which is what lets a page resume without dropping one of them ([validated by: keeps a conversation tied on activity rather than dropping it across a page boundary](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L141)).
    20	- In `InMemorySessionStore` that tie-break is the list's alone: `latestFor` breaks the same tie by creation order, so for two tied conversations the head of the list and the session a resume rejoins can differ ([validated by: breaks a tie on activity by session id, where latestFor takes the session created later](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L42)).
    21	- `MongoSessionStore` answers in order of `updatedAt`, which each `save` moves forward, and its first summary is the session its own `latestFor` returns ([validated by: answers the user's conversations newest saved first, headed by the one latestFor returns](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L31)).
    22	- It breaks a tie by `_id` in both members, so there the head of the list is the session a resume rejoins even when every conversation shares an `updatedAt` ([validated by: heads the list with the session latestFor returns even when every conversation shares an updatedAt](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L161)).
    23	
    24	## What a summary reports
    25	
    26	- `InMemorySessionStore` reports the moment `create` was called, the newest entry time as the activity, and the conversation's entry count ([validated by: reports a creation time, the newest activity and the entry count of each conversation](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L53)).
    27	- `MongoSessionStore` reports the document's `createdAt`, the `updatedAt` its last save wrote, and the counter written beside the entries ([validated by: reports the creation time, the last save and the entry count of each conversation](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L49)).
    28	- That counter is what a save writes, so a list never reads a conversation to count one ([validated by: counts a conversation from the field a save writes beside the entries](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L95)).
    29	- A document written before the counter existed reads as a conversation of no entries rather than failing the list, which is what the backlog documented in `docs/session-stores.md` is for ([validated by: reads a conversation saved before the counter existed as one of no entries, rather than failing](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L79)).
    30	
    31	## Whose conversations
    32	
    33	- A list holds only the asking user's conversations: another user's never appear, and a user with none gets an empty list ([validated by: omits a conversation that aged out and another user's, and answers nothing for a user with none](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L65)).
    34	- `InMemorySessionStore` omits a conversation that has aged out, as `latestFor` does ([validated by: omits a conversation that aged out and another user's, and answers nothing for a user with none](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L65)).
    35	- `MongoSessionStore` filters on the user in the database, sorts on `{updatedAt: -1, _id: -1}` — the `{userId: 1, updatedAt: -1}` index `latestFor` already needs serves its leading keys — and asks for a projection that leaves the entries behind ([validated by: asks the database to filter on the user, sort on the index with the id behind it, and never for the entries](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L108)).
    36	- It answers from that projection alone, so a collection that never returns an entry still lists conversations — the conversation does not leave the database to be listed ([validated by: answers from a projection alone, so a collection that never returns entries still lists conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L181)).
    37	
    38	## Paging
    39	
    40	- `limit` takes that many of the newest, and `before` resumes after a row, so a client pages by passing back the last summary it saw — `SessionCursor` is `updatedAt` and `sessionId`, which a `SessionSummary` already satisfies ([validated by: pages down the same order: a limit takes the newest, and before takes what is older than it](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L78)).
    41	- Paging walks every conversation exactly once even when all of them share an activity time, because the cursor carries the session id the order breaks ties on: a tie cannot fall between two pages and be skipped ([validated by: keeps a conversation tied on activity rather than dropping it across a page boundary](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L141)).
    42	- `MongoSessionStore` pages the same way ([validated by: pages with before and a limit, down the same newest-first order](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L62)).
    43	- It walks a tie exactly once too, through the same cursor ([validated by: keeps a conversation tied on updatedAt rather than dropping it across a page boundary](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L127)).
    44	- A list is at most 200 summaries however many are asked for, and 50 when none is asked for, so no caller can ask for an unbounded page ([validated by: answers at most two hundred conversations however many are asked for, and fifty when none is](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L94)).
    45	- That limit bounds the rows answered, not the rows the database reads to answer them: on `MongoSessionStore` the work is bounded by the `{userId: 1, updatedAt: -1, _id: -1}` index `docs/session-stores.md` prescribes, and under the two-key form Mongo sorts the user's whole history before applying the limit ([validated by: needs the three-key index to answer without sorting the whole history, which the two-key form does not](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L192)).
    46	- A fractional limit is floored rather than refused, since a slip in a limit is not a reason to deny a user their history ([validated by: floors a fractional limit, and reads a negative or unusable one as none given rather than as nothing](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L104)).
